WITH p AS (SELECT value AS j FROM jsonb_array_elements($PAYLOAD$[{"order":1,"title":"القراءة: قائد دون العشرين","content":"القراءة: قائد دون العشرين\n\nالأهداف القابلة للقياس\n• يحدد صفات المسؤولية في نص سردي أصلي.\n• يميّز بين الجرأة المدروسة والاندفاع.\n• يستخرج من النص خطوة للتحقق قبل اتخاذ قرار.\n\nشرح أصلي من ضاديوم\nنص تدريبي جديد لا يطابق كتاب الوزارة: «كان يوسف شابًا يساعد في تنظيم لقاء تعليمي. كُلِّف بتنسيق مجموعة من المتطوعين وهو لم يبلغ العشرين. بدأ بسؤال المشاركين عن احتياجاتهم، وقسم المهام، ثم راجع مع المشرف إجراءات السلامة. وعندما غاب أحدهم عدّل الخطة وأخبر الجميع بالتغيير». لا يدل صغر السن وحده على النجاح أو الفشل، بل تظهر القيادة في الانضباط والإنصات وتحمل المسؤولية. لا ننسب هذه الشخصية التخيلية إلى بطل تاريخي في الكتاب.\n\nأمثلة مستقلة\nالمشكلة غياب مشارك؛ الاستجابة تعديل المهام وإبلاغ الآخرين. القيادة في النص تعاون وتحقق، لا إصدار أوامر دون فهم.\n\nأنشطة تطبيقية متدرجة\nما أول خطوة اتخذها يوسف؟ لماذا راجع إجراءات السلامة؟ اكتب صفتين للقائد وقرارًا يحتاج استشارة المختص.\n\nمفتاح الإجابة والتغذية الراجعة\nسأل عن الاحتياجات؛ لحماية المشاركين؛ تقبل الصبر والتواصل والمسؤولية مع تبريرها من النص.\n\nمن الحياة اليومية\nعند تنسيق نشاط بسيط، دوّن أسماء المهام وراجع توافقها مع قواعد المكان.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يحدد صفات المسؤولية في نص سردي أصلي.","يميّز بين الجرأة المدروسة والاندفاع.","يستخرج من النص خطوة للتحقق قبل اتخاذ قرار."],"vocabulary":[{"word":"تنسيق","meaning":"تنظيم الجهود لتحقيق هدف"},{"word":"قيادة","meaning":"توجيه عمل فريق بمسؤولية"}],"quiz":{"prompt":"ما الذي ميّز تصرف يوسف عند غياب متطوع؟","options":["عدّل الخطة وأبلغ الآخرين","ترك الجميع دون خبر","ألغى السلامة","اتهم المشاركين"],"correct":"عدّل الخطة وأبلغ الآخرين"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":2,"title":"القواعد: الاسم المقصور والاسم المنقوص","content":"القواعد: الاسم المقصور والاسم المنقوص\n\nالأهداف القابلة للقياس\n• يفرق بين الاسم المقصور والمنقوص في أمثلة.\n• يضبط تنوين المنقوص النكرة في حالتي الرفع والجر.\n• يشرح تقدير بعض علامات الإعراب على آخر المقصور.\n\nشرح أصلي من ضاديوم\nالاسم المقصور اسم معرب آخره ألف لازمة مثل «الفتى» و«الهدى»، وتُقدّر الحركات الثلاث على ألفه للتعذر: «جاء الفتى، رأيت الفتى، مررت بالفتى». أما الاسم المنقوص فهو اسم معرب آخره ياء لازمة مكسور ما قبلها مثل «القاضي» و«الداعي»، وتُقدّر الضمة والكسرة على يائه للثقل وتظهر الفتحة في نحو «رأيت القاضيَ». إذا نُكر المنقوص حُذفت ياؤه في الرفع والجر مع التنوين مثل «جاء قاضٍ» و«مررت بقاضٍ»، وتبقى في النصب «رأيت قاضيًا».\n\nأمثلة مستقلة\nفتى مقصور؛ قاضٍ منقوص منكر مرفوع؛ رأيت قاضيًا منقوص منصوب.\n\nأنشطة تطبيقية متدرجة\nصنف «هدى، القاضي، الراعي». لماذا لا تظهر الضمة على ألف «الفتى»؟ أكمل «مررتُ بـ... (قاضٍ)».\n\nمفتاح الإجابة والتغذية الراجعة\nهدى مقصور، القاضي والراعي منقوصان؛ لتعذر الحركة على الألف؛ مررتُ بقاضٍ.\n\nمن الحياة اليومية\nاقرأ إعلانًا قانونيًا عامًا وحدد فيه كلمة «القاضي» إن وجدت، ثم اشرح أثر تعريفها بأل على رسمها.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يفرق بين الاسم المقصور والمنقوص في أمثلة.","يضبط تنوين المنقوص النكرة في حالتي الرفع والجر.","يشرح تقدير بعض علامات الإعراب على آخر المقصور."],"vocabulary":[{"word":"مقصور","meaning":"اسم معرب آخره ألف لازمة"},{"word":"منقوص","meaning":"اسم معرب آخره ياء لازمة مكسور ما قبلها"}],"quiz":{"prompt":"أي كلمة تُعد اسمًا مقصورًا؟","options":["الفتى","القاضي","كاتب","معلم"],"correct":"الفتى"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":3,"title":"القراءة: البحرين في عيون زائريها","content":"القراءة: البحرين في عيون زائريها\n\nالأهداف القابلة للقياس\n• يقرأ انطباعًا سياحيًا أصليًا بصورة ناقدة.\n• يميّز الرأي الشخصي من وصف يمكن التحقق منه.\n• يكتب ملاحظة عن استقبال الزائر.\n\nشرح أصلي من ضاديوم\nنص مستقل من ضاديوم: «وصلت مروة إلى البحرين لحضور فعالية تعليمية. سألت في مكتب الاستقبال عن اتجاه القاعة، فاستعانت بلوحة إرشادية ومساعدة موظفة. لاحظت أن الممرات واضحة والبرنامج يحدد موعد الجلسات. قالت لصديقتها: أسعدني التنظيم وحسن الاستقبال». هذا انطباع لشخصية تخيلية لا يمثل شهادة زائر حقيقي، ويدربنا على فصل الوصف القابل للملاحظة مثل وجود لوحة، عن شعور «أسعدني» الذي يختلف بين الناس.\n\nأمثلة مستقلة\nواقعة في النص التخييلي: وجود لوحة إرشاد. رأي: أعجبني التنظيم. لا يجوز تعميم رأي شخصية على جميع الزائرين.\n\nأنشطة تطبيقية متدرجة\nما وسيلتا الإرشاد اللتان استفادت منهما مروة؟ صنف «أسعدني الاستقبال» إلى رأي أو واقعة. اكتب سطرين مرحبين بزائر.\n\nمفتاح الإجابة والتغذية الراجعة\nاللوحة ومساعدة الموظفة؛ رأي شخصي؛ تقبل رسالة ترحيب واضحة ولطيفة.\n\nمن الحياة اليومية\nاكتب إرشادات طريق قصيرة لضيف يأتي إلى قاعة عامة مع التحقق من اسم القاعة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يقرأ انطباعًا سياحيًا أصليًا بصورة ناقدة.","يميّز الرأي الشخصي من وصف يمكن التحقق منه.","يكتب ملاحظة عن استقبال الزائر."],"vocabulary":[{"word":"انطباع","meaning":"رأي يتكون بعد تجربة"},{"word":"وصف قابل للتحقق","meaning":"معلومة يمكن فحصها في الواقع"}],"quiz":{"prompt":"أي عبارة تعبّر عن رأي شخصي؟","options":["أسعدني التنظيم","وجدت لوحة قرب المدخل","بدأ اللقاء في الموعد المسجل","قُدمت خريطة للقاعات"],"correct":"أسعدني التنظيم"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":4,"title":"الإنتاج الكتابي: تفكيك الموضوع الإنشائي الوصفي إلى عناصره الأساسية","content":"الإنتاج الكتابي: تفكيك الموضوع الإنشائي الوصفي إلى عناصره الأساسية\n\nالأهداف القابلة للقياس\n• يتعرف موضوع الوصف والهدف والجمهور.\n• يحدد ثلاث خصائص دقيقة لمكان أو شخص.\n• ينظم أفكار الوصف في قائمة قبل الكتابة.\n\nشرح أصلي من ضاديوم\nقبل كتابة موضوع وصفي نسأل: ماذا أصف؟ لمن أكتب؟ وما الغرض؟ إذا كان الموضوع «وصف مكتبة الحي»، نجمع عناصر ملموسة: الموقع العام دون بيانات حساسة، المساحة التقريبية دون اختراع أرقام، الإضاءة، ترتيب الرفوف، وسهولة الوصول. نفرق بين الملاحظات الحسية والآراء: «يوجد بابان» ملاحظة إذا تحققنا، أما «أفضل مكتبة» فهو حكم يحتاج مقارنة. خطة الوصف تبدأ بمقدمة تعرّف المكان، ثم جسم يذكر صفاته بترتيب، ثم خاتمة تعكس الفائدة أو الانطباع.\n\nأمثلة مستقلة\nعناصر وصف قاعة: المدخل، المقاعد، السبورة، التهوية. ترتيب ممكن: من الباب إلى النافذة.\n\nأنشطة تطبيقية متدرجة\nقسم «وصف قاعة التعلم» إلى أربعة عناصر. صنف «مريحة جدًا» رأيًا. اكتب مخططًا من مقدمة وثلاث سمات وخاتمة.\n\nمفتاح الإجابة والتغذية الراجعة\nأربعة عناصر مناسبة للقاعة، والرأي «مريحة جدًا» شخصي؛ تقبل خطة واضحة غير مكررة.\n\nمن الحياة اليومية\nقبل كتابة إعلان لمرفق عام عاين المكان ولا تضف صفات لم تتحقق منها.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يتعرف موضوع الوصف والهدف والجمهور.","يحدد ثلاث خصائص دقيقة لمكان أو شخص.","ينظم أفكار الوصف في قائمة قبل الكتابة."],"vocabulary":[{"word":"تفكيك","meaning":"تقسيم موضوع كبير إلى عناصر صغيرة"},{"word":"وصف حسي","meaning":"وصف مبني على ملاحظة مرئية أو مسموعة"}],"quiz":{"prompt":"ما أول خطوة في إعداد وصف دقيق؟","options":["تحديد الشيء والغرض من وصفه","حشو الصفات","تكرار المقدمة","اختلاق الأرقام"],"correct":"تحديد الشيء والغرض من وصفه"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":5,"title":"القواعد: اللازم والمتعدي من الأفعال، والفعل المتعدي إلى مفعولين أصلهما مبتدأ وخبر","content":"القواعد: اللازم والمتعدي من الأفعال، والفعل المتعدي إلى مفعولين أصلهما مبتدأ وخبر\n\nالأهداف القابلة للقياس\n• يفرق بين الفعل اللازم والمتعدي.\n• يعين مفعولين بعد فعل من أفعال القلوب.\n• يعيد المفعولين إلى جملة اسمية مفيدة للتحقق.\n\nشرح أصلي من ضاديوم\nالفعل اللازم يكتفي بالفاعل مثل «جلسَ الدارسُ»، والمتعدي يحتاج مفعولًا أو أكثر لإتمام المعنى مثل «قرأَ الدارسُ الكتابَ». بعض أفعال القلوب تنصب مفعولين أصلهما مبتدأ وخبر، مثل «ظننتُ الجوَّ معتدلًا». أصلهما «الجوُّ معتدلٌ». لا نقول إن كل فعل له مفعولان من هذه الفئة؛ فـ«أعطى» ينصب مفعولين لكن ليس أصلهما مبتدأ وخبر. طريقة الفحص إعادة المفعولين إلى جملة اسمية مستقلة.\n\nأمثلة مستقلة\n«حسبتُ الطالبَ مجتهدًا» تتحول إلى «الطالبُ مجتهدٌ». أما «سلّمتُ رسالةً» فالفعل يتعدى إلى مفعول واحد.\n\nأنشطة تطبيقية متدرجة\nصنف «نام الطفلُ» و«فتح الرجلُ البابَ». حدّد المفعولين في «ظننتُ اللقاءَ قصيرًا». استخرج الجملة الاسمية الأصلية.\n\nمفتاح الإجابة والتغذية الراجعة\nنام لازم، فتح متعدٍ؛ اللقاءَ وقصيرًا؛ أصلهما «اللقاءُ قصيرٌ».\n\nمن الحياة اليومية\nاكتب رأيًا مبدئيًا مستخدمًا «ظننتُ» ثم عدله إذا ظهرت معلومة مؤكدة؛ فالرأي ليس حقيقة قطعية.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يفرق بين الفعل اللازم والمتعدي.","يعين مفعولين بعد فعل من أفعال القلوب.","يعيد المفعولين إلى جملة اسمية مفيدة للتحقق."],"vocabulary":[{"word":"لازم","meaning":"فعل يكتفي بفاعله"},{"word":"فعل قلب","meaning":"فعل يفيد ظنًا أو علمًا في سياق نحوي"}],"quiz":{"prompt":"ما الجملة الأصلية لمفعولي «ظننتُ الطريقَ طويلًا»؟","options":["الطريقُ طويلٌ","الطريقَ طويلًا","ظننتُ الطريق","طويلًا الطريقَ"],"correct":"الطريقُ طويلٌ"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":6,"title":"القراءة: البنفسجة الطموح","content":"القراءة: البنفسجة الطموح\n\nالأهداف القابلة للقياس\n• يستخرج درسًا عن الطموح من نص رمزي أصلي.\n• يميز بين التشخيص الأدبي والواقع العلمي.\n• يكتب نهاية مختلفة تحافظ على قيمة الاجتهاد.\n\nشرح أصلي من ضاديوم\nعنوان الخطة «البنفسجة الطموح»، لكن متن الدرس غير موثق هنا. يقدم ضاديوم نصًا رمزيًا مستقلاً: «في أصيص صغير نمت بنفسجة قرب نافذة. حرصت صاحبة البيت على ضوء مناسب وماء معتدل. تخيل الراوي أن البنفسجة تتمنى أن ترى الحديقة كلها، فلما نقلتها صاحبتها إلى مكان آمن اتسع أمامها المنظر. أدرك الراوي أن النمو يحتاج ظروفًا مناسبة وصبرًا». عبارة «تتمنى البنفسجة» تشخيص أدبي لا ادعاء بأن النبات يفكر كالإنسان. نعالج قيمة الطموح من خلال الصورة دون نسخ نص الكتاب.\n\nأمثلة مستقلة\nالتشخيص: نسبة التمني إلى الزهرة. الواقعة في النص التخييلي: نقل الأصيص إلى مكان مناسب.\n\nأنشطة تطبيقية متدرجة\nحدد موضع التشخيص. لماذا لم يكن النمو فوريًا؟ اكتب نهاية جديدة من ثلاث جمل تربط بين الطموح والعمل والصبر.\n\nمفتاح الإجابة والتغذية الراجعة\n«تتمنى البنفسجة»؛ النمو يحتاج عناية ووقتًا؛ تقبل نهاية رمزية واضحة لا تدّعي حقيقة علمية غير موثقة.\n\nمن الحياة اليومية\nحدد هدفًا دراسيًا صغيرًا واكتب خطوة قابلة للتحقيق اليوم بدل الاكتفاء بتمني النجاح.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يستخرج درسًا عن الطموح من نص رمزي أصلي.","يميز بين التشخيص الأدبي والواقع العلمي.","يكتب نهاية مختلفة تحافظ على قيمة الاجتهاد."],"vocabulary":[{"word":"تشخيص","meaning":"نسبة صفات الإنسان إلى غير الإنسان في الأدب"},{"word":"طموح","meaning":"رغبة في تقدم يصحبها سعي"}],"quiz":{"prompt":"ما العبارة التي تعد تشخيصًا أدبيًا في النص؟","options":["تتمنى البنفسجة رؤية الحديقة","وُضع الأصيص قرب النافذة","سُقي النبات","دخل الضوء"],"correct":"تتمنى البنفسجة رؤية الحديقة"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":7,"title":"الإنتاج الكتابي: إعداد خطة عمل لكتابة فقرة وصفية","content":"الإنتاج الكتابي: إعداد خطة عمل لكتابة فقرة وصفية\n\nالأهداف القابلة للقياس\n• يحدد ترتيبًا واضحًا لأفكار الفقرة الوصفية.\n• يختار جملة موضوعية ثم تفاصيل داعمة.\n• يكتب مخططًا قبل صياغة فقرة من خمس جمل.\n\nشرح أصلي من ضاديوم\nالفقرة الوصفية الجيدة تبدأ بجملة تحدد موضوعها، ثم تضيف صفات مرتبة، وتختم بفكرة مناسبة. لفقرة «قاعة الانتظار» نستطيع استخدام مخطط: جملة عامة عن الوظيفة، وصف للمقاعد، ترتيب الممرات، مكان لوحة الإرشادات، وخاتمة عن سهولة الاستخدام. لا نقفز من لون الجدار إلى رأي في نظام المواعيد دون رابط. نفضل التفاصيل التي نراها فعلًا؛ وإن لم نزُر المكان نقدم الوصف بوصفه تدريبًا تخيليًا.\n\nأمثلة مستقلة\nمخطط وصفي: المكان ← شكله ← أجزاؤه ← استخدامه ← الانطباع النهائي. كل نقطة تصلح أساسًا لجملة.\n\nأنشطة تطبيقية متدرجة\nرتب العبارات «خاتمة، وصف المدخل، تعريف المكان، وصف المقاعد». اكتب مخططًا من خمس نقاط لوصف مكتب صغير، ثم فقرة قصيرة.\n\nمفتاح الإجابة والتغذية الراجعة\nتعريف المكان، وصف المدخل، وصف المقاعد، خاتمة؛ تقبل نقاطًا مرتبة من العام إلى الخاص.\n\nمن الحياة اليومية\nقبل وصف مكان عملك، تأكد من عدم تضمين معلومات أو مستندات خاصة في الفقرة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يحدد ترتيبًا واضحًا لأفكار الفقرة الوصفية.","يختار جملة موضوعية ثم تفاصيل داعمة.","يكتب مخططًا قبل صياغة فقرة من خمس جمل."],"vocabulary":[{"word":"جملة موضوعية","meaning":"جملة تحدد الفكرة الرئيسية"},{"word":"تفصيل داعم","meaning":"صفة أو معلومة توضّح الفكرة"}],"quiz":{"prompt":"ما الدور الأساسي للجملة الأولى في الفقرة الوصفية؟","options":["تحديد الموضوع العام","إضافة نهاية مفاجئة","ذكر كل الصفات","استبعاد التفاصيل"],"correct":"تحديد الموضوع العام"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":8,"title":"القواعد: الفعل المتعدي إلى مفعولين ليس أصلهما المبتدأ والخبر","content":"القواعد: الفعل المتعدي إلى مفعولين ليس أصلهما المبتدأ والخبر\n\nالأهداف القابلة للقياس\n• يميز أفعال الإعطاء ونحوها من أفعال الظن.\n• يستخرج مفعولين لا يصلحان جملة اسمية أصلية.\n• يبني جملة فعلية صحيحة تتعدى إلى مفعولين.\n\nشرح أصلي من ضاديوم\nمن الأفعال التي تنصب مفعولين ليس أصلهما المبتدأ والخبر: «أعطى، منح، كسا» في استعمالاتها المناسبة. نقول «أعطى المديرُ الموظفَ شهادةً»: المدير فاعل، والموظف مفعول به أول، وشهادة مفعول به ثانٍ. لا تصلح عبارة «الموظفُ شهادةٌ» جملة اسمية مؤدية للمعنى المقصود؛ لذا يختلف الفعل عن «ظننتُ الموظفَ نشيطًا» الذي أصله «الموظفُ نشيطٌ». نركز على المعنى قبل تسمية الموقع الإعرابي.\n\nأمثلة مستقلة\n«منحَ المركزُ الدارسَ كتابًا» مفعول أول «الدارسَ» وثانٍ «كتابًا».\n\nأنشطة تطبيقية متدرجة\nحدد المفعولين في «أعطت الأمُّ ابنَها هديةً». ما الفرق بين «منحتُ ساميًا قلمًا» و«ظننتُ ساميًا متفوقًا»؟\n\nمفتاح الإجابة والتغذية الراجعة\nابنَها وهديةً؛ الأول من أفعال الإعطاء ولا يعود إلى جملة اسمية، والثاني من أفعال القلوب وأصله «سامي متفوق».\n\nمن الحياة اليومية\nاكتب وصفًا صحيحًا لإعطاء مستند إلى صاحبه دون الإفصاح عن بيانات شخصية.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يميز أفعال الإعطاء ونحوها من أفعال الظن.","يستخرج مفعولين لا يصلحان جملة اسمية أصلية.","يبني جملة فعلية صحيحة تتعدى إلى مفعولين."],"vocabulary":[{"word":"المفعول الأول","meaning":"الاسم الأول الذي يقع عليه الفعل المتعدي لمفعولين"},{"word":"المفعول الثاني","meaning":"الاسم المكمل لمعنى الفعل بعد الأول"}],"quiz":{"prompt":"ما المفعول الثاني في «منحَ المركزُ الدارسَ شهادةً»؟","options":["شهادةً","الدارسَ","المركزُ","منحَ"],"correct":"شهادةً"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":9,"title":"الإملاء: حذف ألف (ما) الاستفهامية","content":"الإملاء: حذف ألف (ما) الاستفهامية\n\nالأهداف القابلة للقياس\n• يعرف «ما» الاستفهامية بعد حرف الجر.\n• يحذف ألفها كتابة في أمثلة صحيحة.\n• يميز الاستفهام من الموصول في سياق عملي.\n\nشرح أصلي من ضاديوم\nتُحذف ألف «ما» الاستفهامية إذا سبقها حرف جر، ونقول: «بِمَ تفكر؟» أصلها «بـ + ما»، و«لِمَ تأخرت؟» أصلها «لـ + ما»، و«فيمَ تبحث؟» أصلها «في + ما»، و«عَمَّ تتحدث؟» أصلها «عن + ما» مع الإدغام. أما «ما» الموصولة فلا نحذف ألفها في نحو «أعجبتُ بما قرأتُ». لا نقرر الحذف لمجرد رؤية الحرفين «ما»؛ نسأل عن المعنى: هل هي للسؤال أم للوصل؟\n\nأمثلة مستقلة\n«لِمَ غبت؟» سؤال عن السبب؛ «فرحتُ بما نجحت فيه» فيها ما موصولة لا استفهامية.\n\nأنشطة تطبيقية متدرجة\nحوّل «بما تسأل؟» إلى الصيغة الصحيحة إذا قصدت الاستفهام. أكمل «___ تهتم؟» بحرف الجر «في» وما الاستفهامية. صنّف «بما قرأت» في «اهتممت بما قرأت».\n\nمفتاح الإجابة والتغذية الراجعة\nبِمَ تسأل؟؛ «فيمَ تهتم؟»؛ «ما» موصولة في «اهتممت بما قرأت».\n\nمن الحياة اليومية\nراجع أسئلة الاستبيان مثل «بمَ تقترح البدء؟» لسلامة الرسم والوضوح.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يعرف «ما» الاستفهامية بعد حرف الجر.","يحذف ألفها كتابة في أمثلة صحيحة.","يميز الاستفهام من الموصول في سياق عملي."],"vocabulary":[{"word":"ما الاستفهامية","meaning":"أداة للسؤال عن الشيء"},{"word":"ما الموصولة","meaning":"اسم يصل جملة بأخرى"}],"quiz":{"prompt":"ما الرسم الصحيح عند سؤال يبدأ بحرف الجر «لـ»؟","options":["لِمَ تأخرت؟","لِما تأخرت؟","لما تأخرت؟ على أنها موصولة","لماذا بلا سياق"],"correct":"لِمَ تأخرت؟"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":10,"title":"الإنتاج الكتابي: كتابة قصة تتضمن مقطعًا وصفيًا (وصف شخص خِلقيًا وخُلقيًا)","content":"الإنتاج الكتابي: كتابة قصة تتضمن مقطعًا وصفيًا (وصف شخص خِلقيًا وخُلقيًا)\n\nالأهداف القابلة للقياس\n• يميز الصفات الخَلقية عن الخُلقية.\n• يدمج الوصف في حدث سردي دون تعطيل الحركة.\n• يكتب وصفًا محترمًا لا يختزل الأشخاص في مظهرهم.\n\nشرح أصلي من ضاديوم\nيصف السرد الشخصيات من جانبين: الخِلقي يتعلق بالمظهر الخارجي كالملابس وطريقة الحركة دون إصدار أحكام، والخُلقي يتعلق بالسلوك مثل الأمانة والصبر. نص تدريبي: «وصلت هناء إلى قاعة التدريب تحمل ملفًا أزرق. كانت خطواتها هادئة، واستقبلت زميلتها الجديدة بابتسامة وعرضت عليها المقعد الفارغ». الملف الأزرق وحركة الخطى مشهد بصري، أما العرض على الزميلة فهو سلوك يدل على التعاون. نتجنب التنمر أو تخمين خلق شخص من شكله.\n\nأمثلة مستقلة\n«كان يرتدي معطفًا رماديًا» وصف ظاهر، و«أعاد الكتاب لصاحبه» سلوك يدل على الأمانة.\n\nأنشطة تطبيقية متدرجة\nعيّن وصفًا خِلقيًا وآخر خُلقيًا في النص. اكتب قصة قصيرة من ست جمل تبرز أخلاق الشخصية بفعل، لا بنعت عام وحده.\n\nمفتاح الإجابة والتغذية الراجعة\nالخطوات الهادئة أو الملف الأزرق وصف خارجي؛ استقبال الزميلة والتعاون سلوك خُلقي؛ تقبل قصة تبرهن الصفة من الحدث.\n\nمن الحياة اليومية\nعند التعريف بزميل جديد، اذكر عمله الإيجابي بدل إصدار حكم على مظهره.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يميز الصفات الخَلقية عن الخُلقية.","يدمج الوصف في حدث سردي دون تعطيل الحركة.","يكتب وصفًا محترمًا لا يختزل الأشخاص في مظهرهم."],"vocabulary":[{"word":"خِلقي","meaning":"متصل بالمظهر الخارجي"},{"word":"خُلقي","meaning":"متصل بالقيم والسلوك"}],"quiz":{"prompt":"أي عبارة تصف خُلُقًا من خلال فعل؟","options":["أعاد الأمانة إلى صاحبها","يرتدي قميصًا أزرق","شعره قصير","حقيبته كبيرة"],"correct":"أعاد الأمانة إلى صاحبها"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":11,"title":"الإملاء: مراجعة رسم الهمزة المتوسطة","content":"الإملاء: مراجعة رسم الهمزة المتوسطة\n\nالأهداف القابلة للقياس\n• يراجع ترتيب قوة الحركات في رسم الهمزة.\n• يميز كرسي الهمزة في كلمات من حياته.\n• يشرح سبب رسم همزة على ألف أو واو أو ياء.\n\nشرح أصلي من ضاديوم\nعند رسم الهمزة المتوسطة نقارن حركة الهمزة بحركة ما قبلها. ترتيب القوة عمومًا الكسرة ثم الضمة ثم الفتحة ثم السكون. الكسرة تناسب النبرة «سُئِل»، والضمة تناسب الواو «مَسْؤُول»، والفتحة تناسب الألف «سَأَل». لا نلغي الاستثناءات السياقية، لكن هذه نقطة بداية عملية. نقرأ الكلمة بالحركات قبل رسم الكرسي ونقارن مثالين متشابهين يختلفان في المعنى والحركات.\n\nأمثلة مستقلة\n«سَأَلَ» للمعلوم على ألف، و«سُئِلَ» للمجهول على نبرة. كلمة «مسؤول» همزتها مضمومة بعد سكون.\n\nأنشطة تطبيقية متدرجة\nاكتب «سأل» و«سئل» واضبط كلًّا منهما. اشرح سبب رسم «مسؤول» على واو. صنف «فئة» تحت الكرسي الصحيح.\n\nمفتاح الإجابة والتغذية الراجعة\nسَأَلَ، سُئِلَ؛ الضمة أقوى من السكون، فناسبتها الواو؛ «فئة» على نبرة.\n\nمن الحياة اليومية\nراجع كتابة طلب رسمي يتضمن كلمات «مسؤول» و«رئيس» مع الاستعانة بمعجم موثوق عند الشك.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يراجع ترتيب قوة الحركات في رسم الهمزة.","يميز كرسي الهمزة في كلمات من حياته.","يشرح سبب رسم همزة على ألف أو واو أو ياء."],"vocabulary":[{"word":"الهمزة المتوسطة","meaning":"همزة تقع بين حروف الكلمة"},{"word":"كرسي","meaning":"ألف أو واو أو نبرة تحمل الهمزة"}],"quiz":{"prompt":"ما الكرسي المناسب لهمزة «سُئِلَ»؟","options":["النبرة","الواو","الألف","السطر"],"correct":"النبرة"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":12,"title":"القراءة: حب وإيمان - دراسة القصيدة كاملة، والحفظ من 9 إلى 14","content":"القراءة: حب وإيمان - دراسة القصيدة كاملة، والحفظ من 9 إلى 14\n\nالأهداف القابلة للقياس\n• يستخرج فكرة الإخلاص من نص أصلي مستقل.\n• يميز العاطفة من المعلومة المباشرة.\n• يفصل تدريبات القراءة عن القصيدة الرسمية المطلوبة للحفظ.\n\nشرح أصلي من ضاديوم\nتسجل الخطة قصيدة «حب وإيمان» مع دراسة القصيدة كاملة وحفظ الأبيات 9 إلى 14، لكن النص المعتمد لم تتم مطابقته هنا. لذلك لا ننقل بيتًا أو ننسب عبارة إلى الشاعر. نص ضاديوم الداعم: «كان أمين يساعد زميلًا كبير السن على قراءة الاستمارة. لم ينتظر شكرًا، بل شرح الكلمات بهدوء حتى تمكن الزميل من قراءتها وحده. شعر أمين أن العمل النافع يكون أجمل عندما تصحبه نية طيبة». النثر مستقل يدرب على فهم قيمة الإخلاص وملاحظة أثر المساعدة.\n\nأمثلة مستقلة\nالفعل الدال على الإخلاص: تقديم المساعدة دون انتظار شكر. الأثر: قدرة الزميل على القراءة وحده.\n\nأنشطة تطبيقية متدرجة\nما العمل الذي قدمه أمين؟ كيف ظهر أثر المساعدة؟ اكتب ثلاث جمل أصلية عن أثر حسن النية في عمل جماعي. لا تعد هذه السطور أبياتًا للحفظ.\n\nمفتاح الإجابة والتغذية الراجعة\nساعد زميله في الاستمارة؛ أصبح قادرًا على القراءة؛ تقبل جملًا محددة عن سلوك نافع.\n\nمن الحياة اليومية\nساعد من يحتاج شرحًا في مركز التعلم مع احترام استقلاله وخصوصيته.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يستخرج فكرة الإخلاص من نص أصلي مستقل.","يميز العاطفة من المعلومة المباشرة.","يفصل تدريبات القراءة عن القصيدة الرسمية المطلوبة للحفظ."],"vocabulary":[{"word":"إخلاص","meaning":"قصد الخير دون طلب مدح"},{"word":"أثر","meaning":"نتيجة تظهر بعد فعل"}],"quiz":{"prompt":"هل النص المقدم هنا هو الأبيات الرسمية للحفظ؟","options":["لا، نص نثري داعم مستقل","نعم الأبيات 9–14","نعم صورة من الكتاب","نعم قصيدة مكتملة موثقة"],"correct":"لا، نص نثري داعم مستقل"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":13,"title":"الإنتاج الكتابي: كتابة بطاقة التهنئة","content":"الإنتاج الكتابي: كتابة بطاقة التهنئة\n\nالأهداف القابلة للقياس\n• يحدد المناسبة والمتلقي في بطاقة تهنئة.\n• يكتب عبارة إيجابية ملائمة للموقف.\n• يراجع علامات الترقيم وصحة اسم المخاطب.\n\nشرح أصلي من ضاديوم\nبطاقة التهنئة رسالة موجزة لمشاركة شعور إيجابي في مناسبة محددة، مثل نجاح أو إتمام دورة أو مناسبة أسرية. تبدأ بتحية مناسبة وتذكر المناسبة بوضوح ثم تعبر عن فرح أو تمنٍّ طيب، وتختم باسم المرسل إن كانت شخصية. مثال أصلي: «إلى زميلتي سلمى، أبارك لك إتمام دورة القراءة. أتمنى لك مزيدًا من التقدم والثقة. زميلتك هدى». لا نفترض حصول حدث لم يؤكد صاحبه، ولا نكشف معلومة خاصة دون إذنه.\n\nأمثلة مستقلة\nالتهنئة تختلف عن الدعوة؛ الأولى تعبر عن مشاركة الفرح بعد مناسبة، والثانية تطلب الحضور إلى حدث.\n\nأنشطة تطبيقية متدرجة\nحدد المناسبة في البطاقة النموذجية. اكتب بطاقة تهنئة من ثلاثة أسطر لزميل افتراضي نجح في اختبار. راجع اسم المخاطب وعلامة النهاية.\n\nمفتاح الإجابة والتغذية الراجعة\nالمناسبة إتمام دورة القراءة؛ تقبل بطاقة صادقة ومهذبة واضحة الغرض والمرسل.\n\nمن الحياة اليومية\nقدّم تهنئة قصيرة لشخص يستحقها بعد التحقق من المناسبة وبما يلائم درجة المعرفة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يحدد المناسبة والمتلقي في بطاقة تهنئة.","يكتب عبارة إيجابية ملائمة للموقف.","يراجع علامات الترقيم وصحة اسم المخاطب."],"vocabulary":[{"word":"تهنئة","meaning":"مشاركة الفرح بالمناسبة"},{"word":"مخاطب","meaning":"الشخص الذي تتوجه إليه الرسالة"}],"quiz":{"prompt":"أي عبارة مناسبة لبطاقة تهنئة بالنجاح؟","options":["أبارك لك نجاحك وأتمنى دوام التقدم","أنت مدعو إلى قاعة الساعة الخامسة","أطلب مستندًا","يرجى تعبئة النموذج"],"correct":"أبارك لك نجاحك وأتمنى دوام التقدم"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":14,"title":"القواعد: المفعول المطلق","content":"القواعد: المفعول المطلق\n\nالأهداف القابلة للقياس\n• يتعرف المفعول المطلق بوصفه مصدرًا منصوبًا.\n• يميز وظيفتي التوكيد وبيان النوع.\n• يصوغ جملة بمفعول مطلق ملائم لفعلها.\n\nشرح أصلي من ضاديوم\nالمفعول المطلق مصدر منصوب يذكر بعد فعل من لفظه غالبًا لتوكيده أو بيان نوعه أو عدده. «قرأَ الدارسُ قراءةً» يوضح المصدر المؤكد لفعل القراءة، و«قرأَ قراءةً متأنيةً» يبين نوعها. في «دققتُ البابَ دقتينِ» المفعول المطلق يبين العدد وقد يأتي مثنى. لا نخلط بين المصدر المنصوب وبين المفعول به: في «قرأَ الدارسُ الكتابَ قراءةً متأنيةً» الكتاب مفعول به و«قراءةً» مفعول مطلق.\n\nأمثلة مستقلة\n«فرحَ الطفلُ فرحًا» للتوكيد. «عملَ العاملُ عملًا متقنًا» لبيان النوع.\n\nأنشطة تطبيقية متدرجة\nحدد المفعول المطلق في «انتصر الفريقُ انتصارًا». ما وظيفته في «سارَ سيرًا سريعًا»؟ اكتب جملة بمفعول مطلق من لفظ «تعاون».\n\nمفتاح الإجابة والتغذية الراجعة\nانتصارًا؛ بيان النوع بالصفة سريعًا؛ مثال «تعاون الفريقُ تعاونًا مثمرًا».\n\nمن الحياة اليومية\nاكتب وصفًا لجهد بذلته مستخدمًا مصدرًا منصوبًا يوضح نوع الجهد دون مبالغة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يتعرف المفعول المطلق بوصفه مصدرًا منصوبًا.","يميز وظيفتي التوكيد وبيان النوع.","يصوغ جملة بمفعول مطلق ملائم لفعلها."],"vocabulary":[{"word":"مصدر","meaning":"اسم يدل على الحدث مجردًا من الزمن"},{"word":"مفعول مطلق","meaning":"مصدر منصوب يبين معنى الفعل أو نوعه أو عدده"}],"quiz":{"prompt":"ما المفعول المطلق في «تعلّمَ الدارسُ تعلّمًا جيدًا»؟","options":["تعلّمًا","الدارسُ","تعلّمَ","جيدًا وحدها"],"correct":"تعلّمًا"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"}]$PAYLOAD$::jsonb)),
target AS (
 SELECT l.id,p.j FROM p
 JOIN lessons l ON l.title=p.j->>'title' AND l.sort_order=(p.j->>'order')::integer
 JOIN units u ON u.id=l.unit_id AND u.semester=1
 JOIN grades g ON g.id=u.grade_id AND g.name_ar='الأول تقوية' AND g.grade_number IS NULL
 JOIN curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN countries co ON co.id=cu.country_id AND co.code='BH'
 WHERE l.content='محتوى مقرر في الخطة الرسمية الحالية. يُحفظ العنوان كما في المصدر بعد تنظيف أخطاء OCR الشكلية فقط.' AND l.learning_objectives='[]'::jsonb AND l.instructions='[]'::jsonb
)
UPDATE lessons l SET content=t.j->>'content',learning_objectives=t.j->'learning_objectives',
 vocabulary=t.j->'vocabulary',instructions=jsonb_build_array(jsonb_build_object('origin','DADYOOM_BH_REINFORCEMENT1_DRAFT_V1','editorial_review','required','book_text_copied',false)),updated_at=now()
FROM target t WHERE l.id=t.id;

WITH p AS (SELECT value AS j FROM jsonb_array_elements($PAYLOAD$[{"order":1,"title":"القراءة: قائد دون العشرين","content":"القراءة: قائد دون العشرين\n\nالأهداف القابلة للقياس\n• يحدد صفات المسؤولية في نص سردي أصلي.\n• يميّز بين الجرأة المدروسة والاندفاع.\n• يستخرج من النص خطوة للتحقق قبل اتخاذ قرار.\n\nشرح أصلي من ضاديوم\nنص تدريبي جديد لا يطابق كتاب الوزارة: «كان يوسف شابًا يساعد في تنظيم لقاء تعليمي. كُلِّف بتنسيق مجموعة من المتطوعين وهو لم يبلغ العشرين. بدأ بسؤال المشاركين عن احتياجاتهم، وقسم المهام، ثم راجع مع المشرف إجراءات السلامة. وعندما غاب أحدهم عدّل الخطة وأخبر الجميع بالتغيير». لا يدل صغر السن وحده على النجاح أو الفشل، بل تظهر القيادة في الانضباط والإنصات وتحمل المسؤولية. لا ننسب هذه الشخصية التخيلية إلى بطل تاريخي في الكتاب.\n\nأمثلة مستقلة\nالمشكلة غياب مشارك؛ الاستجابة تعديل المهام وإبلاغ الآخرين. القيادة في النص تعاون وتحقق، لا إصدار أوامر دون فهم.\n\nأنشطة تطبيقية متدرجة\nما أول خطوة اتخذها يوسف؟ لماذا راجع إجراءات السلامة؟ اكتب صفتين للقائد وقرارًا يحتاج استشارة المختص.\n\nمفتاح الإجابة والتغذية الراجعة\nسأل عن الاحتياجات؛ لحماية المشاركين؛ تقبل الصبر والتواصل والمسؤولية مع تبريرها من النص.\n\nمن الحياة اليومية\nعند تنسيق نشاط بسيط، دوّن أسماء المهام وراجع توافقها مع قواعد المكان.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يحدد صفات المسؤولية في نص سردي أصلي.","يميّز بين الجرأة المدروسة والاندفاع.","يستخرج من النص خطوة للتحقق قبل اتخاذ قرار."],"vocabulary":[{"word":"تنسيق","meaning":"تنظيم الجهود لتحقيق هدف"},{"word":"قيادة","meaning":"توجيه عمل فريق بمسؤولية"}],"quiz":{"prompt":"ما الذي ميّز تصرف يوسف عند غياب متطوع؟","options":["عدّل الخطة وأبلغ الآخرين","ترك الجميع دون خبر","ألغى السلامة","اتهم المشاركين"],"correct":"عدّل الخطة وأبلغ الآخرين"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":2,"title":"القواعد: الاسم المقصور والاسم المنقوص","content":"القواعد: الاسم المقصور والاسم المنقوص\n\nالأهداف القابلة للقياس\n• يفرق بين الاسم المقصور والمنقوص في أمثلة.\n• يضبط تنوين المنقوص النكرة في حالتي الرفع والجر.\n• يشرح تقدير بعض علامات الإعراب على آخر المقصور.\n\nشرح أصلي من ضاديوم\nالاسم المقصور اسم معرب آخره ألف لازمة مثل «الفتى» و«الهدى»، وتُقدّر الحركات الثلاث على ألفه للتعذر: «جاء الفتى، رأيت الفتى، مررت بالفتى». أما الاسم المنقوص فهو اسم معرب آخره ياء لازمة مكسور ما قبلها مثل «القاضي» و«الداعي»، وتُقدّر الضمة والكسرة على يائه للثقل وتظهر الفتحة في نحو «رأيت القاضيَ». إذا نُكر المنقوص حُذفت ياؤه في الرفع والجر مع التنوين مثل «جاء قاضٍ» و«مررت بقاضٍ»، وتبقى في النصب «رأيت قاضيًا».\n\nأمثلة مستقلة\nفتى مقصور؛ قاضٍ منقوص منكر مرفوع؛ رأيت قاضيًا منقوص منصوب.\n\nأنشطة تطبيقية متدرجة\nصنف «هدى، القاضي، الراعي». لماذا لا تظهر الضمة على ألف «الفتى»؟ أكمل «مررتُ بـ... (قاضٍ)».\n\nمفتاح الإجابة والتغذية الراجعة\nهدى مقصور، القاضي والراعي منقوصان؛ لتعذر الحركة على الألف؛ مررتُ بقاضٍ.\n\nمن الحياة اليومية\nاقرأ إعلانًا قانونيًا عامًا وحدد فيه كلمة «القاضي» إن وجدت، ثم اشرح أثر تعريفها بأل على رسمها.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يفرق بين الاسم المقصور والمنقوص في أمثلة.","يضبط تنوين المنقوص النكرة في حالتي الرفع والجر.","يشرح تقدير بعض علامات الإعراب على آخر المقصور."],"vocabulary":[{"word":"مقصور","meaning":"اسم معرب آخره ألف لازمة"},{"word":"منقوص","meaning":"اسم معرب آخره ياء لازمة مكسور ما قبلها"}],"quiz":{"prompt":"أي كلمة تُعد اسمًا مقصورًا؟","options":["الفتى","القاضي","كاتب","معلم"],"correct":"الفتى"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":3,"title":"القراءة: البحرين في عيون زائريها","content":"القراءة: البحرين في عيون زائريها\n\nالأهداف القابلة للقياس\n• يقرأ انطباعًا سياحيًا أصليًا بصورة ناقدة.\n• يميّز الرأي الشخصي من وصف يمكن التحقق منه.\n• يكتب ملاحظة عن استقبال الزائر.\n\nشرح أصلي من ضاديوم\nنص مستقل من ضاديوم: «وصلت مروة إلى البحرين لحضور فعالية تعليمية. سألت في مكتب الاستقبال عن اتجاه القاعة، فاستعانت بلوحة إرشادية ومساعدة موظفة. لاحظت أن الممرات واضحة والبرنامج يحدد موعد الجلسات. قالت لصديقتها: أسعدني التنظيم وحسن الاستقبال». هذا انطباع لشخصية تخيلية لا يمثل شهادة زائر حقيقي، ويدربنا على فصل الوصف القابل للملاحظة مثل وجود لوحة، عن شعور «أسعدني» الذي يختلف بين الناس.\n\nأمثلة مستقلة\nواقعة في النص التخييلي: وجود لوحة إرشاد. رأي: أعجبني التنظيم. لا يجوز تعميم رأي شخصية على جميع الزائرين.\n\nأنشطة تطبيقية متدرجة\nما وسيلتا الإرشاد اللتان استفادت منهما مروة؟ صنف «أسعدني الاستقبال» إلى رأي أو واقعة. اكتب سطرين مرحبين بزائر.\n\nمفتاح الإجابة والتغذية الراجعة\nاللوحة ومساعدة الموظفة؛ رأي شخصي؛ تقبل رسالة ترحيب واضحة ولطيفة.\n\nمن الحياة اليومية\nاكتب إرشادات طريق قصيرة لضيف يأتي إلى قاعة عامة مع التحقق من اسم القاعة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يقرأ انطباعًا سياحيًا أصليًا بصورة ناقدة.","يميّز الرأي الشخصي من وصف يمكن التحقق منه.","يكتب ملاحظة عن استقبال الزائر."],"vocabulary":[{"word":"انطباع","meaning":"رأي يتكون بعد تجربة"},{"word":"وصف قابل للتحقق","meaning":"معلومة يمكن فحصها في الواقع"}],"quiz":{"prompt":"أي عبارة تعبّر عن رأي شخصي؟","options":["أسعدني التنظيم","وجدت لوحة قرب المدخل","بدأ اللقاء في الموعد المسجل","قُدمت خريطة للقاعات"],"correct":"أسعدني التنظيم"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":4,"title":"الإنتاج الكتابي: تفكيك الموضوع الإنشائي الوصفي إلى عناصره الأساسية","content":"الإنتاج الكتابي: تفكيك الموضوع الإنشائي الوصفي إلى عناصره الأساسية\n\nالأهداف القابلة للقياس\n• يتعرف موضوع الوصف والهدف والجمهور.\n• يحدد ثلاث خصائص دقيقة لمكان أو شخص.\n• ينظم أفكار الوصف في قائمة قبل الكتابة.\n\nشرح أصلي من ضاديوم\nقبل كتابة موضوع وصفي نسأل: ماذا أصف؟ لمن أكتب؟ وما الغرض؟ إذا كان الموضوع «وصف مكتبة الحي»، نجمع عناصر ملموسة: الموقع العام دون بيانات حساسة، المساحة التقريبية دون اختراع أرقام، الإضاءة، ترتيب الرفوف، وسهولة الوصول. نفرق بين الملاحظات الحسية والآراء: «يوجد بابان» ملاحظة إذا تحققنا، أما «أفضل مكتبة» فهو حكم يحتاج مقارنة. خطة الوصف تبدأ بمقدمة تعرّف المكان، ثم جسم يذكر صفاته بترتيب، ثم خاتمة تعكس الفائدة أو الانطباع.\n\nأمثلة مستقلة\nعناصر وصف قاعة: المدخل، المقاعد، السبورة، التهوية. ترتيب ممكن: من الباب إلى النافذة.\n\nأنشطة تطبيقية متدرجة\nقسم «وصف قاعة التعلم» إلى أربعة عناصر. صنف «مريحة جدًا» رأيًا. اكتب مخططًا من مقدمة وثلاث سمات وخاتمة.\n\nمفتاح الإجابة والتغذية الراجعة\nأربعة عناصر مناسبة للقاعة، والرأي «مريحة جدًا» شخصي؛ تقبل خطة واضحة غير مكررة.\n\nمن الحياة اليومية\nقبل كتابة إعلان لمرفق عام عاين المكان ولا تضف صفات لم تتحقق منها.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يتعرف موضوع الوصف والهدف والجمهور.","يحدد ثلاث خصائص دقيقة لمكان أو شخص.","ينظم أفكار الوصف في قائمة قبل الكتابة."],"vocabulary":[{"word":"تفكيك","meaning":"تقسيم موضوع كبير إلى عناصر صغيرة"},{"word":"وصف حسي","meaning":"وصف مبني على ملاحظة مرئية أو مسموعة"}],"quiz":{"prompt":"ما أول خطوة في إعداد وصف دقيق؟","options":["تحديد الشيء والغرض من وصفه","حشو الصفات","تكرار المقدمة","اختلاق الأرقام"],"correct":"تحديد الشيء والغرض من وصفه"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":5,"title":"القواعد: اللازم والمتعدي من الأفعال، والفعل المتعدي إلى مفعولين أصلهما مبتدأ وخبر","content":"القواعد: اللازم والمتعدي من الأفعال، والفعل المتعدي إلى مفعولين أصلهما مبتدأ وخبر\n\nالأهداف القابلة للقياس\n• يفرق بين الفعل اللازم والمتعدي.\n• يعين مفعولين بعد فعل من أفعال القلوب.\n• يعيد المفعولين إلى جملة اسمية مفيدة للتحقق.\n\nشرح أصلي من ضاديوم\nالفعل اللازم يكتفي بالفاعل مثل «جلسَ الدارسُ»، والمتعدي يحتاج مفعولًا أو أكثر لإتمام المعنى مثل «قرأَ الدارسُ الكتابَ». بعض أفعال القلوب تنصب مفعولين أصلهما مبتدأ وخبر، مثل «ظننتُ الجوَّ معتدلًا». أصلهما «الجوُّ معتدلٌ». لا نقول إن كل فعل له مفعولان من هذه الفئة؛ فـ«أعطى» ينصب مفعولين لكن ليس أصلهما مبتدأ وخبر. طريقة الفحص إعادة المفعولين إلى جملة اسمية مستقلة.\n\nأمثلة مستقلة\n«حسبتُ الطالبَ مجتهدًا» تتحول إلى «الطالبُ مجتهدٌ». أما «سلّمتُ رسالةً» فالفعل يتعدى إلى مفعول واحد.\n\nأنشطة تطبيقية متدرجة\nصنف «نام الطفلُ» و«فتح الرجلُ البابَ». حدّد المفعولين في «ظننتُ اللقاءَ قصيرًا». استخرج الجملة الاسمية الأصلية.\n\nمفتاح الإجابة والتغذية الراجعة\nنام لازم، فتح متعدٍ؛ اللقاءَ وقصيرًا؛ أصلهما «اللقاءُ قصيرٌ».\n\nمن الحياة اليومية\nاكتب رأيًا مبدئيًا مستخدمًا «ظننتُ» ثم عدله إذا ظهرت معلومة مؤكدة؛ فالرأي ليس حقيقة قطعية.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يفرق بين الفعل اللازم والمتعدي.","يعين مفعولين بعد فعل من أفعال القلوب.","يعيد المفعولين إلى جملة اسمية مفيدة للتحقق."],"vocabulary":[{"word":"لازم","meaning":"فعل يكتفي بفاعله"},{"word":"فعل قلب","meaning":"فعل يفيد ظنًا أو علمًا في سياق نحوي"}],"quiz":{"prompt":"ما الجملة الأصلية لمفعولي «ظننتُ الطريقَ طويلًا»؟","options":["الطريقُ طويلٌ","الطريقَ طويلًا","ظننتُ الطريق","طويلًا الطريقَ"],"correct":"الطريقُ طويلٌ"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":6,"title":"القراءة: البنفسجة الطموح","content":"القراءة: البنفسجة الطموح\n\nالأهداف القابلة للقياس\n• يستخرج درسًا عن الطموح من نص رمزي أصلي.\n• يميز بين التشخيص الأدبي والواقع العلمي.\n• يكتب نهاية مختلفة تحافظ على قيمة الاجتهاد.\n\nشرح أصلي من ضاديوم\nعنوان الخطة «البنفسجة الطموح»، لكن متن الدرس غير موثق هنا. يقدم ضاديوم نصًا رمزيًا مستقلاً: «في أصيص صغير نمت بنفسجة قرب نافذة. حرصت صاحبة البيت على ضوء مناسب وماء معتدل. تخيل الراوي أن البنفسجة تتمنى أن ترى الحديقة كلها، فلما نقلتها صاحبتها إلى مكان آمن اتسع أمامها المنظر. أدرك الراوي أن النمو يحتاج ظروفًا مناسبة وصبرًا». عبارة «تتمنى البنفسجة» تشخيص أدبي لا ادعاء بأن النبات يفكر كالإنسان. نعالج قيمة الطموح من خلال الصورة دون نسخ نص الكتاب.\n\nأمثلة مستقلة\nالتشخيص: نسبة التمني إلى الزهرة. الواقعة في النص التخييلي: نقل الأصيص إلى مكان مناسب.\n\nأنشطة تطبيقية متدرجة\nحدد موضع التشخيص. لماذا لم يكن النمو فوريًا؟ اكتب نهاية جديدة من ثلاث جمل تربط بين الطموح والعمل والصبر.\n\nمفتاح الإجابة والتغذية الراجعة\n«تتمنى البنفسجة»؛ النمو يحتاج عناية ووقتًا؛ تقبل نهاية رمزية واضحة لا تدّعي حقيقة علمية غير موثقة.\n\nمن الحياة اليومية\nحدد هدفًا دراسيًا صغيرًا واكتب خطوة قابلة للتحقيق اليوم بدل الاكتفاء بتمني النجاح.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يستخرج درسًا عن الطموح من نص رمزي أصلي.","يميز بين التشخيص الأدبي والواقع العلمي.","يكتب نهاية مختلفة تحافظ على قيمة الاجتهاد."],"vocabulary":[{"word":"تشخيص","meaning":"نسبة صفات الإنسان إلى غير الإنسان في الأدب"},{"word":"طموح","meaning":"رغبة في تقدم يصحبها سعي"}],"quiz":{"prompt":"ما العبارة التي تعد تشخيصًا أدبيًا في النص؟","options":["تتمنى البنفسجة رؤية الحديقة","وُضع الأصيص قرب النافذة","سُقي النبات","دخل الضوء"],"correct":"تتمنى البنفسجة رؤية الحديقة"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":7,"title":"الإنتاج الكتابي: إعداد خطة عمل لكتابة فقرة وصفية","content":"الإنتاج الكتابي: إعداد خطة عمل لكتابة فقرة وصفية\n\nالأهداف القابلة للقياس\n• يحدد ترتيبًا واضحًا لأفكار الفقرة الوصفية.\n• يختار جملة موضوعية ثم تفاصيل داعمة.\n• يكتب مخططًا قبل صياغة فقرة من خمس جمل.\n\nشرح أصلي من ضاديوم\nالفقرة الوصفية الجيدة تبدأ بجملة تحدد موضوعها، ثم تضيف صفات مرتبة، وتختم بفكرة مناسبة. لفقرة «قاعة الانتظار» نستطيع استخدام مخطط: جملة عامة عن الوظيفة، وصف للمقاعد، ترتيب الممرات، مكان لوحة الإرشادات، وخاتمة عن سهولة الاستخدام. لا نقفز من لون الجدار إلى رأي في نظام المواعيد دون رابط. نفضل التفاصيل التي نراها فعلًا؛ وإن لم نزُر المكان نقدم الوصف بوصفه تدريبًا تخيليًا.\n\nأمثلة مستقلة\nمخطط وصفي: المكان ← شكله ← أجزاؤه ← استخدامه ← الانطباع النهائي. كل نقطة تصلح أساسًا لجملة.\n\nأنشطة تطبيقية متدرجة\nرتب العبارات «خاتمة، وصف المدخل، تعريف المكان، وصف المقاعد». اكتب مخططًا من خمس نقاط لوصف مكتب صغير، ثم فقرة قصيرة.\n\nمفتاح الإجابة والتغذية الراجعة\nتعريف المكان، وصف المدخل، وصف المقاعد، خاتمة؛ تقبل نقاطًا مرتبة من العام إلى الخاص.\n\nمن الحياة اليومية\nقبل وصف مكان عملك، تأكد من عدم تضمين معلومات أو مستندات خاصة في الفقرة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يحدد ترتيبًا واضحًا لأفكار الفقرة الوصفية.","يختار جملة موضوعية ثم تفاصيل داعمة.","يكتب مخططًا قبل صياغة فقرة من خمس جمل."],"vocabulary":[{"word":"جملة موضوعية","meaning":"جملة تحدد الفكرة الرئيسية"},{"word":"تفصيل داعم","meaning":"صفة أو معلومة توضّح الفكرة"}],"quiz":{"prompt":"ما الدور الأساسي للجملة الأولى في الفقرة الوصفية؟","options":["تحديد الموضوع العام","إضافة نهاية مفاجئة","ذكر كل الصفات","استبعاد التفاصيل"],"correct":"تحديد الموضوع العام"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":8,"title":"القواعد: الفعل المتعدي إلى مفعولين ليس أصلهما المبتدأ والخبر","content":"القواعد: الفعل المتعدي إلى مفعولين ليس أصلهما المبتدأ والخبر\n\nالأهداف القابلة للقياس\n• يميز أفعال الإعطاء ونحوها من أفعال الظن.\n• يستخرج مفعولين لا يصلحان جملة اسمية أصلية.\n• يبني جملة فعلية صحيحة تتعدى إلى مفعولين.\n\nشرح أصلي من ضاديوم\nمن الأفعال التي تنصب مفعولين ليس أصلهما المبتدأ والخبر: «أعطى، منح، كسا» في استعمالاتها المناسبة. نقول «أعطى المديرُ الموظفَ شهادةً»: المدير فاعل، والموظف مفعول به أول، وشهادة مفعول به ثانٍ. لا تصلح عبارة «الموظفُ شهادةٌ» جملة اسمية مؤدية للمعنى المقصود؛ لذا يختلف الفعل عن «ظننتُ الموظفَ نشيطًا» الذي أصله «الموظفُ نشيطٌ». نركز على المعنى قبل تسمية الموقع الإعرابي.\n\nأمثلة مستقلة\n«منحَ المركزُ الدارسَ كتابًا» مفعول أول «الدارسَ» وثانٍ «كتابًا».\n\nأنشطة تطبيقية متدرجة\nحدد المفعولين في «أعطت الأمُّ ابنَها هديةً». ما الفرق بين «منحتُ ساميًا قلمًا» و«ظننتُ ساميًا متفوقًا»؟\n\nمفتاح الإجابة والتغذية الراجعة\nابنَها وهديةً؛ الأول من أفعال الإعطاء ولا يعود إلى جملة اسمية، والثاني من أفعال القلوب وأصله «سامي متفوق».\n\nمن الحياة اليومية\nاكتب وصفًا صحيحًا لإعطاء مستند إلى صاحبه دون الإفصاح عن بيانات شخصية.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يميز أفعال الإعطاء ونحوها من أفعال الظن.","يستخرج مفعولين لا يصلحان جملة اسمية أصلية.","يبني جملة فعلية صحيحة تتعدى إلى مفعولين."],"vocabulary":[{"word":"المفعول الأول","meaning":"الاسم الأول الذي يقع عليه الفعل المتعدي لمفعولين"},{"word":"المفعول الثاني","meaning":"الاسم المكمل لمعنى الفعل بعد الأول"}],"quiz":{"prompt":"ما المفعول الثاني في «منحَ المركزُ الدارسَ شهادةً»؟","options":["شهادةً","الدارسَ","المركزُ","منحَ"],"correct":"شهادةً"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":9,"title":"الإملاء: حذف ألف (ما) الاستفهامية","content":"الإملاء: حذف ألف (ما) الاستفهامية\n\nالأهداف القابلة للقياس\n• يعرف «ما» الاستفهامية بعد حرف الجر.\n• يحذف ألفها كتابة في أمثلة صحيحة.\n• يميز الاستفهام من الموصول في سياق عملي.\n\nشرح أصلي من ضاديوم\nتُحذف ألف «ما» الاستفهامية إذا سبقها حرف جر، ونقول: «بِمَ تفكر؟» أصلها «بـ + ما»، و«لِمَ تأخرت؟» أصلها «لـ + ما»، و«فيمَ تبحث؟» أصلها «في + ما»، و«عَمَّ تتحدث؟» أصلها «عن + ما» مع الإدغام. أما «ما» الموصولة فلا نحذف ألفها في نحو «أعجبتُ بما قرأتُ». لا نقرر الحذف لمجرد رؤية الحرفين «ما»؛ نسأل عن المعنى: هل هي للسؤال أم للوصل؟\n\nأمثلة مستقلة\n«لِمَ غبت؟» سؤال عن السبب؛ «فرحتُ بما نجحت فيه» فيها ما موصولة لا استفهامية.\n\nأنشطة تطبيقية متدرجة\nحوّل «بما تسأل؟» إلى الصيغة الصحيحة إذا قصدت الاستفهام. أكمل «___ تهتم؟» بحرف الجر «في» وما الاستفهامية. صنّف «بما قرأت» في «اهتممت بما قرأت».\n\nمفتاح الإجابة والتغذية الراجعة\nبِمَ تسأل؟؛ «فيمَ تهتم؟»؛ «ما» موصولة في «اهتممت بما قرأت».\n\nمن الحياة اليومية\nراجع أسئلة الاستبيان مثل «بمَ تقترح البدء؟» لسلامة الرسم والوضوح.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يعرف «ما» الاستفهامية بعد حرف الجر.","يحذف ألفها كتابة في أمثلة صحيحة.","يميز الاستفهام من الموصول في سياق عملي."],"vocabulary":[{"word":"ما الاستفهامية","meaning":"أداة للسؤال عن الشيء"},{"word":"ما الموصولة","meaning":"اسم يصل جملة بأخرى"}],"quiz":{"prompt":"ما الرسم الصحيح عند سؤال يبدأ بحرف الجر «لـ»؟","options":["لِمَ تأخرت؟","لِما تأخرت؟","لما تأخرت؟ على أنها موصولة","لماذا بلا سياق"],"correct":"لِمَ تأخرت؟"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":10,"title":"الإنتاج الكتابي: كتابة قصة تتضمن مقطعًا وصفيًا (وصف شخص خِلقيًا وخُلقيًا)","content":"الإنتاج الكتابي: كتابة قصة تتضمن مقطعًا وصفيًا (وصف شخص خِلقيًا وخُلقيًا)\n\nالأهداف القابلة للقياس\n• يميز الصفات الخَلقية عن الخُلقية.\n• يدمج الوصف في حدث سردي دون تعطيل الحركة.\n• يكتب وصفًا محترمًا لا يختزل الأشخاص في مظهرهم.\n\nشرح أصلي من ضاديوم\nيصف السرد الشخصيات من جانبين: الخِلقي يتعلق بالمظهر الخارجي كالملابس وطريقة الحركة دون إصدار أحكام، والخُلقي يتعلق بالسلوك مثل الأمانة والصبر. نص تدريبي: «وصلت هناء إلى قاعة التدريب تحمل ملفًا أزرق. كانت خطواتها هادئة، واستقبلت زميلتها الجديدة بابتسامة وعرضت عليها المقعد الفارغ». الملف الأزرق وحركة الخطى مشهد بصري، أما العرض على الزميلة فهو سلوك يدل على التعاون. نتجنب التنمر أو تخمين خلق شخص من شكله.\n\nأمثلة مستقلة\n«كان يرتدي معطفًا رماديًا» وصف ظاهر، و«أعاد الكتاب لصاحبه» سلوك يدل على الأمانة.\n\nأنشطة تطبيقية متدرجة\nعيّن وصفًا خِلقيًا وآخر خُلقيًا في النص. اكتب قصة قصيرة من ست جمل تبرز أخلاق الشخصية بفعل، لا بنعت عام وحده.\n\nمفتاح الإجابة والتغذية الراجعة\nالخطوات الهادئة أو الملف الأزرق وصف خارجي؛ استقبال الزميلة والتعاون سلوك خُلقي؛ تقبل قصة تبرهن الصفة من الحدث.\n\nمن الحياة اليومية\nعند التعريف بزميل جديد، اذكر عمله الإيجابي بدل إصدار حكم على مظهره.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يميز الصفات الخَلقية عن الخُلقية.","يدمج الوصف في حدث سردي دون تعطيل الحركة.","يكتب وصفًا محترمًا لا يختزل الأشخاص في مظهرهم."],"vocabulary":[{"word":"خِلقي","meaning":"متصل بالمظهر الخارجي"},{"word":"خُلقي","meaning":"متصل بالقيم والسلوك"}],"quiz":{"prompt":"أي عبارة تصف خُلُقًا من خلال فعل؟","options":["أعاد الأمانة إلى صاحبها","يرتدي قميصًا أزرق","شعره قصير","حقيبته كبيرة"],"correct":"أعاد الأمانة إلى صاحبها"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":11,"title":"الإملاء: مراجعة رسم الهمزة المتوسطة","content":"الإملاء: مراجعة رسم الهمزة المتوسطة\n\nالأهداف القابلة للقياس\n• يراجع ترتيب قوة الحركات في رسم الهمزة.\n• يميز كرسي الهمزة في كلمات من حياته.\n• يشرح سبب رسم همزة على ألف أو واو أو ياء.\n\nشرح أصلي من ضاديوم\nعند رسم الهمزة المتوسطة نقارن حركة الهمزة بحركة ما قبلها. ترتيب القوة عمومًا الكسرة ثم الضمة ثم الفتحة ثم السكون. الكسرة تناسب النبرة «سُئِل»، والضمة تناسب الواو «مَسْؤُول»، والفتحة تناسب الألف «سَأَل». لا نلغي الاستثناءات السياقية، لكن هذه نقطة بداية عملية. نقرأ الكلمة بالحركات قبل رسم الكرسي ونقارن مثالين متشابهين يختلفان في المعنى والحركات.\n\nأمثلة مستقلة\n«سَأَلَ» للمعلوم على ألف، و«سُئِلَ» للمجهول على نبرة. كلمة «مسؤول» همزتها مضمومة بعد سكون.\n\nأنشطة تطبيقية متدرجة\nاكتب «سأل» و«سئل» واضبط كلًّا منهما. اشرح سبب رسم «مسؤول» على واو. صنف «فئة» تحت الكرسي الصحيح.\n\nمفتاح الإجابة والتغذية الراجعة\nسَأَلَ، سُئِلَ؛ الضمة أقوى من السكون، فناسبتها الواو؛ «فئة» على نبرة.\n\nمن الحياة اليومية\nراجع كتابة طلب رسمي يتضمن كلمات «مسؤول» و«رئيس» مع الاستعانة بمعجم موثوق عند الشك.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يراجع ترتيب قوة الحركات في رسم الهمزة.","يميز كرسي الهمزة في كلمات من حياته.","يشرح سبب رسم همزة على ألف أو واو أو ياء."],"vocabulary":[{"word":"الهمزة المتوسطة","meaning":"همزة تقع بين حروف الكلمة"},{"word":"كرسي","meaning":"ألف أو واو أو نبرة تحمل الهمزة"}],"quiz":{"prompt":"ما الكرسي المناسب لهمزة «سُئِلَ»؟","options":["النبرة","الواو","الألف","السطر"],"correct":"النبرة"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":12,"title":"القراءة: حب وإيمان - دراسة القصيدة كاملة، والحفظ من 9 إلى 14","content":"القراءة: حب وإيمان - دراسة القصيدة كاملة، والحفظ من 9 إلى 14\n\nالأهداف القابلة للقياس\n• يستخرج فكرة الإخلاص من نص أصلي مستقل.\n• يميز العاطفة من المعلومة المباشرة.\n• يفصل تدريبات القراءة عن القصيدة الرسمية المطلوبة للحفظ.\n\nشرح أصلي من ضاديوم\nتسجل الخطة قصيدة «حب وإيمان» مع دراسة القصيدة كاملة وحفظ الأبيات 9 إلى 14، لكن النص المعتمد لم تتم مطابقته هنا. لذلك لا ننقل بيتًا أو ننسب عبارة إلى الشاعر. نص ضاديوم الداعم: «كان أمين يساعد زميلًا كبير السن على قراءة الاستمارة. لم ينتظر شكرًا، بل شرح الكلمات بهدوء حتى تمكن الزميل من قراءتها وحده. شعر أمين أن العمل النافع يكون أجمل عندما تصحبه نية طيبة». النثر مستقل يدرب على فهم قيمة الإخلاص وملاحظة أثر المساعدة.\n\nأمثلة مستقلة\nالفعل الدال على الإخلاص: تقديم المساعدة دون انتظار شكر. الأثر: قدرة الزميل على القراءة وحده.\n\nأنشطة تطبيقية متدرجة\nما العمل الذي قدمه أمين؟ كيف ظهر أثر المساعدة؟ اكتب ثلاث جمل أصلية عن أثر حسن النية في عمل جماعي. لا تعد هذه السطور أبياتًا للحفظ.\n\nمفتاح الإجابة والتغذية الراجعة\nساعد زميله في الاستمارة؛ أصبح قادرًا على القراءة؛ تقبل جملًا محددة عن سلوك نافع.\n\nمن الحياة اليومية\nساعد من يحتاج شرحًا في مركز التعلم مع احترام استقلاله وخصوصيته.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يستخرج فكرة الإخلاص من نص أصلي مستقل.","يميز العاطفة من المعلومة المباشرة.","يفصل تدريبات القراءة عن القصيدة الرسمية المطلوبة للحفظ."],"vocabulary":[{"word":"إخلاص","meaning":"قصد الخير دون طلب مدح"},{"word":"أثر","meaning":"نتيجة تظهر بعد فعل"}],"quiz":{"prompt":"هل النص المقدم هنا هو الأبيات الرسمية للحفظ؟","options":["لا، نص نثري داعم مستقل","نعم الأبيات 9–14","نعم صورة من الكتاب","نعم قصيدة مكتملة موثقة"],"correct":"لا، نص نثري داعم مستقل"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":13,"title":"الإنتاج الكتابي: كتابة بطاقة التهنئة","content":"الإنتاج الكتابي: كتابة بطاقة التهنئة\n\nالأهداف القابلة للقياس\n• يحدد المناسبة والمتلقي في بطاقة تهنئة.\n• يكتب عبارة إيجابية ملائمة للموقف.\n• يراجع علامات الترقيم وصحة اسم المخاطب.\n\nشرح أصلي من ضاديوم\nبطاقة التهنئة رسالة موجزة لمشاركة شعور إيجابي في مناسبة محددة، مثل نجاح أو إتمام دورة أو مناسبة أسرية. تبدأ بتحية مناسبة وتذكر المناسبة بوضوح ثم تعبر عن فرح أو تمنٍّ طيب، وتختم باسم المرسل إن كانت شخصية. مثال أصلي: «إلى زميلتي سلمى، أبارك لك إتمام دورة القراءة. أتمنى لك مزيدًا من التقدم والثقة. زميلتك هدى». لا نفترض حصول حدث لم يؤكد صاحبه، ولا نكشف معلومة خاصة دون إذنه.\n\nأمثلة مستقلة\nالتهنئة تختلف عن الدعوة؛ الأولى تعبر عن مشاركة الفرح بعد مناسبة، والثانية تطلب الحضور إلى حدث.\n\nأنشطة تطبيقية متدرجة\nحدد المناسبة في البطاقة النموذجية. اكتب بطاقة تهنئة من ثلاثة أسطر لزميل افتراضي نجح في اختبار. راجع اسم المخاطب وعلامة النهاية.\n\nمفتاح الإجابة والتغذية الراجعة\nالمناسبة إتمام دورة القراءة؛ تقبل بطاقة صادقة ومهذبة واضحة الغرض والمرسل.\n\nمن الحياة اليومية\nقدّم تهنئة قصيرة لشخص يستحقها بعد التحقق من المناسبة وبما يلائم درجة المعرفة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يحدد المناسبة والمتلقي في بطاقة تهنئة.","يكتب عبارة إيجابية ملائمة للموقف.","يراجع علامات الترقيم وصحة اسم المخاطب."],"vocabulary":[{"word":"تهنئة","meaning":"مشاركة الفرح بالمناسبة"},{"word":"مخاطب","meaning":"الشخص الذي تتوجه إليه الرسالة"}],"quiz":{"prompt":"أي عبارة مناسبة لبطاقة تهنئة بالنجاح؟","options":["أبارك لك نجاحك وأتمنى دوام التقدم","أنت مدعو إلى قاعة الساعة الخامسة","أطلب مستندًا","يرجى تعبئة النموذج"],"correct":"أبارك لك نجاحك وأتمنى دوام التقدم"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"},{"order":14,"title":"القواعد: المفعول المطلق","content":"القواعد: المفعول المطلق\n\nالأهداف القابلة للقياس\n• يتعرف المفعول المطلق بوصفه مصدرًا منصوبًا.\n• يميز وظيفتي التوكيد وبيان النوع.\n• يصوغ جملة بمفعول مطلق ملائم لفعلها.\n\nشرح أصلي من ضاديوم\nالمفعول المطلق مصدر منصوب يذكر بعد فعل من لفظه غالبًا لتوكيده أو بيان نوعه أو عدده. «قرأَ الدارسُ قراءةً» يوضح المصدر المؤكد لفعل القراءة، و«قرأَ قراءةً متأنيةً» يبين نوعها. في «دققتُ البابَ دقتينِ» المفعول المطلق يبين العدد وقد يأتي مثنى. لا نخلط بين المصدر المنصوب وبين المفعول به: في «قرأَ الدارسُ الكتابَ قراءةً متأنيةً» الكتاب مفعول به و«قراءةً» مفعول مطلق.\n\nأمثلة مستقلة\n«فرحَ الطفلُ فرحًا» للتوكيد. «عملَ العاملُ عملًا متقنًا» لبيان النوع.\n\nأنشطة تطبيقية متدرجة\nحدد المفعول المطلق في «انتصر الفريقُ انتصارًا». ما وظيفته في «سارَ سيرًا سريعًا»؟ اكتب جملة بمفعول مطلق من لفظ «تعاون».\n\nمفتاح الإجابة والتغذية الراجعة\nانتصارًا؛ بيان النوع بالصفة سريعًا؛ مثال «تعاون الفريقُ تعاونًا مثمرًا».\n\nمن الحياة اليومية\nاكتب وصفًا لجهد بذلته مستخدمًا مصدرًا منصوبًا يوضح نوع الجهد دون مبالغة.\n\nتنبيه التوثيق: المادة من تأليف ضاديوم لدعم العنوان المسجل في خطة التعليم المستمر بمملكة البحرين 2026–2027 وليست متن الكتاب الرسمي ولا دليلًا على مطابقة فهرسه. النصوص الشعرية ومقاطع الحفظ الرسمية تنتظر تحققًا من مصدرها الأصلي. يلزم اعتماد تربوي تحريري منفصل.\nSOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1","learning_objectives":["يتعرف المفعول المطلق بوصفه مصدرًا منصوبًا.","يميز وظيفتي التوكيد وبيان النوع.","يصوغ جملة بمفعول مطلق ملائم لفعلها."],"vocabulary":[{"word":"مصدر","meaning":"اسم يدل على الحدث مجردًا من الزمن"},{"word":"مفعول مطلق","meaning":"مصدر منصوب يبين معنى الفعل أو نوعه أو عدده"}],"quiz":{"prompt":"ما المفعول المطلق في «تعلّمَ الدارسُ تعلّمًا جيدًا»؟","options":["تعلّمًا","الدارسُ","تعلّمَ","جيدًا وحدها"],"correct":"تعلّمًا"},"editorialReview":"required","bookTextCopied":false,"origin":"DADYOOM_BH_REINFORCEMENT1_DRAFT_V1"}]$PAYLOAD$::jsonb))
INSERT INTO lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
SELECT l.id,'سؤال فهم وتطبيق من ضاديوم','multiple_choice',
 'تدريب داعم أصلي من ضاديوم. اختر الإجابة الصحيحة الوحيدة.',
 jsonb_build_object('origin','DADYOOM_BH_REINFORCEMENT1_MCQ_V1','selection_mode','single','options',p.j->'quiz'->'options','editorial_review','required','book_text_copied',false),
 1,5,true,'assessment',p.j->'quiz'->>'prompt',jsonb_build_object('correct',p.j->'quiz'->>'correct'),false
FROM p
JOIN lessons l ON l.title=p.j->>'title' AND l.sort_order=(p.j->>'order')::integer AND l.content LIKE '%SOURCE=DADYOOM_BH_REINFORCEMENT1_DRAFT_V1%'
JOIN units u ON u.id=l.unit_id AND u.semester=1
JOIN grades g ON g.id=u.grade_id AND g.name_ar='الأول تقوية' AND g.grade_number IS NULL
JOIN curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
JOIN countries co ON co.id=cu.country_id AND co.code='BH'
WHERE NOT EXISTS (SELECT 1 FROM lesson_activities a WHERE a.lesson_id=l.id AND a.content->>'origin'='DADYOOM_BH_REINFORCEMENT1_MCQ_V1');